    [19845]={name="Zandalar Illusionist's Mantle",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Illusionist's Mantle'. Starts with Al'tabim the All-Seeing in Stranglethorn Vale. Objective: Bring Al'tabim the All-Seeing a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Mantle",lore="How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."},
    [19846]={name="Zandalar Illusionist's Wraps",quality=4,ilvl=61,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Illusionist's Wraps'. Starts with Al'tabim the All-Seeing in Stranglethorn Vale. Objective: Bring Al'tabim the All-Seeing Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.Al'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.",zone="Zul'Gurub",questName="Paragons of Power: The Illusionist's Wraps",lore="For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."},
    [19876]={name="Soul Corrupter's Necklace",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
    [19893]={name="Zanzil's Seal",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Bloodlord Mandokir.",zone="Zul'Gurub",npc="Bloodlord Mandokir"},
